(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20 + Math.cos(y*0.013-t*0.22)*15;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.5)*8 + Math.cos(sy*0.02+t*0.4)*6;
  const w2y = Math.cos(sy*0.022+t*0.45)*7 + Math.sin(sx*0.018-t*0.55)*5;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1.0],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2.0],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3.0],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 4.0],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 5.0],
    [80+Math.sin(t*0.65+3)*70, 50+Math.cos(t*0.75+2)*50, 0.11, 2.1, 1.5],
    [400+Math.cos(t*0.45+1)*60, 210+Math.sin(t*0.85)*40, 0.085, 1.8, 4.5]
  ];
  let aS = 0, iS = 0, cross = 0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
    const w = Math.sin(d*f*1.5 - t*0.8)*0.15;
    aS += Math.sin((d+w)*f - t*sp + ph);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5 + ph*0.5);
    cross += Math.sin(d*f*0.5 - t*sp*0.4 + ph) * Math.cos(d*f*0.3 + t*sp*0.8 - ph*0.3);
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, crs = cross/n;
  const bg1 = (Math.sin(fx*0.035+fy*0.022+t*0.7) + Math.sin(fx*0.028-fy*0.038+t*1.0))/2;
  const bg2 = Math.sin((fx+fy)*0.11+t*2.2)*0.2 + Math.sin((fx-fy)*0.09-t*1.8)*0.2;
  const bg3 = Math.sin(fx*0.06*Math.cos(t*0.2)+fy*0.05*Math.sin(t*0.15)+t*0.6)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((fx-cx)**2 + (fy-cy)**2);
  const ang = Math.atan2(fy-cy, fx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.035+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.06-ang*2+t*0.8)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const voronoi = (() => {
    let md = 999, sd = 999;
    for (const [sX, sY] of src) {
      const d = Math.sqrt((fx-sX)**2 + (fy-sY)**2);
      if (d < md) { sd = md; md = d; } else if (d < sd) { sd = d; }
    }
    return (sd - md) * 0.15;
  })();
  const membrane = Math.tanh(voronoi * 3 - 0.5) * 0.4;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.3 + spiral + crs*0.4)*2.0);
  const rd2 = Math.tanh((act*0.8 - inh + bg*0.2 - crs*0.3 + membrane)*1.8);
  const feedback = Math.sin(rd1*Math.PI)*Math.cos(rd2*Math.PI*0.7);
  const cell = Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14) + Math.sin((fx+fy)*0.09+t)*0.5 + feedback*0.3)*1.5)*0.25;
  const micro = Math.sin(fx*0.3+t*3)*Math.sin(fy*0.3-t*2.5)*0.08;
  const blend = rd1*0.45 + rd2*0.25 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,35,82],[12,62,105],[18,95,120],[30,135,125],
    [80,168,118],[160,195,80],[210,190,55],[225,150,60],
    [210,100,65],[185,60,72],[140,35,75],[85,22,68],[40,15,58],[5,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx - i;
  const edge = Math.abs(rd1)>0.65 ? 1.2 : Math.abs(rd2)>0.6 ? 1.1 : 1.0;
  const glow = Math.max(0, 1 - dist/200)*0.15;
  const lum = 0.85 + Math.sin(rd1*Math.PI)*0.15 + glow;
  const breath = 0.95 + Math.sin(t*0.4)*0.05;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*breath)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*breath)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*breath)|0
  ];
}
